const dynamic = { name: "env", variable: "DYNAMIC" };

export function ordinary() {
  return Deno.env.get("SECRET");
}

export function query() {
  return Deno.permissions.querySync(dynamic).state;
}

export function request() {
  return Deno.permissions.requestSync(dynamic).state;
}

export async function importData() {
  return await import("data:text/javascript,export const value = 42");
}

export function createWorker() {
  return new Worker("data:application/javascript,close()", { type: "module" });
}
